import {SAVE,META,CLASSES,SLOTS,catalog,stats,emptyGear,newRun,loadRun,serialize,reroll,master,purchase,fight,tick,settle} from './arena-engine.mjs';
import {assets,hero,gearImage} from './arena-art.mjs';
const $=s=>document.querySelector(s),screen=$('#screen'),canvas=$('#scene'),ctx=canvas.getContext('2d');
let meta={thorn:false},run=null,storageOK=true;
try{meta.thorn=JSON.parse(localStorage.getItem(META))?.thorn===true;run=loadRun(localStorage.getItem(SAVE),meta);}catch{storageOK=false;}
let view=run?'lobby':'choose',chosen='dwarf',slot='melee',tier=1,battle=null,art,W=innerWidth,H=innerHeight,time=0,previous=0,acc=0,held={},taps={},floating=[],message='';
const labels={hp:'Health',melee:'Melee',ranged:'Range',defense:'Armor',magic:'Magic',speed:'Speed',boots:'Boots'};
function save(){try{localStorage.setItem(META,JSON.stringify(meta));if(run)localStorage.setItem(SAVE,serialize(run));}catch{storageOK=false;}}
const sources=new Map();
function clearInput(){sources.clear();held={};taps={};document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));}
function paused(){return $('#menu').open||$('#confirm').open||document.hidden;}
function statsHTML(st,base){return `<div class="stats">${['hp','melee','ranged','defense','magic','speed'].map(k=>`<span><small>${labels[k]}</small><b>${st[k]}</b>${base?`<em>${st[k]-base[k]>0?'+':''}${st[k]-base[k]}</em>`:''}</span>`).join('')}</div>`;}
function render(){clearInput();$('#fight-ui').hidden=view!=='fight';$('#shop-open').hidden=!run||view==='choose'||view==='fight'||view==='shop';$('#coins').textContent=run&&view!=='choose'?`${run.gold} gold`:'';screen.innerHTML='';
 if(view==='choose'){const keys=['dwarf','ranger','mage'];if(meta.thorn)keys.push('thorn');screen.innerHTML=`<div class="heading"><h1>Choose your fighter</h1><p class="muted">One small weapon. A crown to earn.</p></div><div class="hero-picks">${keys.map(k=>`<button data-hero="${k}" class="${chosen===k?'active':''}" aria-pressed="${chosen===k}"><strong>${CLASSES[k].name}</strong>${CLASSES[k].title}<small>${CLASSES[k].trait}</small></button>`).join('')}</div><div class="foot"><button id="begin" class="gold">Begin as ${CLASSES[chosen].name}</button><p class="muted">${meta.thorn?'Thornkeeper unlocked':'Defeat the master to unlock a new fighter'}</p></div>`;screen.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{chosen=b.dataset.hero;render();});$('#begin').onclick=()=>{run=newRun(chosen,meta);save();view='lobby';render();};}
 if(view==='lobby'){if(run.finished){view='result';render();return;}const offers=run.wins===5?[master()]:run.offers.length?run.offers:reroll(run);save();const mine=stats(run.hero,run.gear);screen.innerHTML=`<div class="heading"><h1>${run.wins===5?'The master awaits':'Pick your opponent'}</h1><div class="route" aria-label="${run.wins} of 5 wins">${Array.from({length:5},(_,i)=>`<i class="${i<run.wins?'done':''}"></i>`).join('')}<span>♛</span></div><p class="muted">${run.wins===5?'Win to unlock Thornkeeper for future journeys':`${run.wins}/5 wins before the master · Compare their stats with yours`}</p></div><p class="your-line">You · ${Object.entries(mine).filter(([k])=>labels[k]).map(([k,v])=>`${labels[k]} ${v}`).join(' · ')}</p><div class="offers">${offers.map((o,i)=>`<div class="opponent"><h2>${o.name}</h2><p class="muted">${CLASSES[o.hero].title} · ${o.style}</p>${statsHTML(stats(o.hero,o.gear),mine)}<p class="gearline">${catalog(o.hero,'melee')[o.gear.melee].name} · ${catalog(o.hero,'defense')[o.gear.defense].name}</p><button class="gold" data-fight="${i}">Fight · ${o.prize} gold</button></div>`).join('')}</div><div class="foot">${run.wins<5?'<button id="reroll">Find two others ↻</button>':''}<button id="lobby-shop">Visit shop</button></div>`;screen.querySelectorAll('[data-fight]').forEach(b=>b.onclick=()=>startFight(offers[+b.dataset.fight]));if($('#reroll'))$('#reroll').onclick=()=>{reroll(run);render();};$('#lobby-shop').onclick=openShop;}
 if(view==='shop'){const items=catalog(run.hero,slot),item=items[tier],equipped=run.gear[slot],preview={...run.gear,[slot]:tier},before=stats(run.hero,run.gear),after=stats(run.hero,preview);const stat=slot==='boots'?'speed':slot;screen.innerHTML=`<section class="shop-view"><h1>${CLASSES[run.hero].name}'s outfitter</h1><div class="fitting-space"></div><div class="rack"><div class="tabs" role="tablist" aria-label="Equipment category">${SLOTS.map(s=>`<button role="tab" aria-selected="${s===slot}" class="${s===slot?'active':''}" data-slot="${s}">${labels[s]}</button>`).join('')}</div><div class="items">${items.map(i=>`<button data-tier="${i.tier}" class="${tier===i.tier?'active':''}" aria-label="Preview ${i.name}"><canvas width="100" height="120"></canvas><small>${i.tier===equipped?'Equipped':i.tier<equipped?'Earlier gear':i.price+' gold'}</small></button>`).join('')}</div><h2>${item.name}</h2><p>${labels[stat]} ${before[stat]} → ${after[stat]}${slot==='defense'?' · Heavier armor slows movement':slot==='boots'?' · Higher jumps too':''}</p><p class="muted" role="status">${message||'Try it on. Test it before you buy.'}</p><div class="buttons"><button id="buy" class="gold" ${tier<=equipped||run.gold<item.price?'disabled':''}>${tier===equipped?'Equipped':tier<equipped?'Already surpassed':run.gold<item.price?`Need ${item.price-run.gold} more gold`:`Buy · ${item.price} gold`}</button><button id="try">Try in arena</button></div></div><footer><span>Previewing gear on your fighter</span><button id="shop-back">Back</button></footer></section>`;screen.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{slot=b.dataset.slot;tier=Math.min(4,run.gear[slot]+1);message='';render();});screen.querySelectorAll('[data-tier]').forEach(b=>{b.onclick=()=>{tier=+b.dataset.tier;message='';render();};const c=b.querySelector('canvas'),x=c.getContext('2d'),im=gearImage(art,run.hero,slot,+b.dataset.tier),scale=Math.min(90/im.width,112/im.height);x.drawImage(im,(100-im.width*scale)/2,(120-im.height*scale)/2,im.width*scale,im.height*scale);});$('#buy').onclick=()=>{if(purchase(run,slot,tier)){message='Equipped!';save();render();}};$('#try').onclick=()=>startFight({hero:'dwarf',gear:emptyGear(),name:'Training partner',level:1,prize:0,arena:'Moss arena'},true,preview);$('#shop-back').onclick=()=>{view='lobby';render();};}
 if(view==='fight'){const f=battle;$('#pname').textContent=CLASSES[run.hero].name;$('#ename').textContent=f.offer.name;$('#training-exit').hidden=!f.training;$('#training-exit').onclick=()=>{view='shop';battle=null;render();};}
 if(view==='result'){const won=battle?.outcome==='win'||run.finished;screen.innerHTML=`<div class="result"><h1>${battle?.badge||'Crown claimed!'}</h1><p class="reward">${battle&&won?`+${battle.offer.prize} gold`:run.finished?'Thornkeeper unlocked!':'No gold lost'}</p><p>${run.finished?'Choose Thornkeeper when you start your next journey.':won?'A stronger fighter. One step closer.':'Read the wind-up. Choose your moment.'}</p>${run.finished?'<button id="again" class="gold">New journey</button>':'<button id="next" class="gold">Choose opponent</button><button id="result-shop">Shop</button>'}</div>`;if($('#next'))$('#next').onclick=()=>{battle=null;view='lobby';render();};if($('#result-shop'))$('#result-shop').onclick=openShop;if($('#again'))$('#again').onclick=()=>$('#confirm').showModal();}
}
function openShop(){slot='melee';tier=Math.min(4,run.gear.melee+1);message='';view='shop';render();}
function startFight(offer,training=false,gear){battle=fight(gear?{...run,gear}:run,offer,training);floating=[];view='fight';render();}
$('#shop-open').onclick=openShop;$('#menu-open').onclick=()=>{clearInput();$('#retreat').hidden=view!=='fight';$('#new-journey').hidden=!run;$('#storage-note').textContent=storageOK?'Progress saves on this browser. Leaving a fight returns to opponent selection.':'Saving is unavailable in this browser. Keep this tab open to retain progress.';$('#menu').showModal();document.body.classList.add('paused');};$('#resume').onclick=()=>$('#menu').close();$('#menu').addEventListener('close',()=>{clearInput();document.body.classList.remove('paused');});$('#retreat').onclick=()=>{$('#menu').close();view=battle?.training?'shop':'lobby';battle=null;render();};$('#new-journey').onclick=()=>{$('#menu').close();$('#confirm').showModal();};$('#cancel-new').onclick=()=>$('#confirm').close();$('#confirm-new').onclick=()=>{$('#confirm').close();battle=null;run=null;try{localStorage.removeItem(SAVE);}catch{storageOK=false;}view='choose';chosen='dwarf';render();};
const map={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',Space:'jump',KeyJ:'attack',KeyU:'ranged',KeyL:'magic',KeyK:'guard'};
function press(k,source){if(view!=='fight'||paused())return;sources.set(source,k);held[k]=true;taps[k]=true;document.querySelector(`[data-key="${k}"]`)?.classList.add('pressed');}
function release(k,source){sources.delete(source);held[k]=[...sources.values()].includes(k);if(held[k])return;document.querySelector(`[data-key="${k}"]`)?.classList.remove('pressed');}
addEventListener('keydown',e=>{if(!map[e.code]||view!=='fight'||paused())return;e.preventDefault();if(!e.repeat)press(map[e.code],e.code);});addEventListener('keyup',e=>{if(map[e.code])release(map[e.code],e.code);});addEventListener('blur',clearInput);document.addEventListener('visibilitychange',clearInput);
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(b.dataset.key,e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,e=>release(b.dataset.key,e.pointerId));}
function resize(){W=innerWidth;H=innerHeight;const d=Math.min(2,devicePixelRatio||1);canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0);}addEventListener('resize',resize);resize();
function draw(){ctx.clearRect(0,0,W,H);const bg=art.forest,s=Math.max(W/bg.width,H/bg.height);ctx.drawImage(bg,(W-bg.width*s)/2,(H-bg.height*s)/2,bg.width*s,bg.height*s);ctx.fillStyle=battle?.offer.arena==='Moonlit ring'?'#26175188':'#0b332847';ctx.fillRect(0,0,W,H);const shade=ctx.createLinearGradient(0,H*.4,0,H);shade.addColorStop(0,'#09271a00');shade.addColorStop(1,'#071f18ef');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);
 const ground=H*.68,unit=W/920;const drawActor=a=>{const x=a.x*unit,y=ground-a.y*unit;hero(ctx,art,a.hero,x,y,a.gear,{time,walk:a.walk,moving:a.moving,face:a.face,attack:a.attack,hurt:a.hurt,scale:Math.max(.55,Math.min(1,unit*.8))});if(a.guard){ctx.strokeStyle='#a8eeff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y-70*unit,65*unit,-1.5,1.5);ctx.stroke();}};
 if(view==='fight'||view==='result'&&battle){drawActor(battle.p);drawActor(battle.e);for(const b of battle.projectiles){ctx.fillStyle=b.kind==='magic'?'#d2a3ff':'#ffe5ac';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.beginPath();ctx.ellipse(b.x*unit,ground-b.y*unit,b.kind==='magic'?9:12,b.kind==='magic'?9:3,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}if(battle.e.windup){ctx.fillStyle='#ffda91';ctx.font='bold 16px Nunito, sans-serif';ctx.textAlign='center';ctx.fillText(battle.e.windup.kind==='attack'?'Melee!':battle.e.windup.kind==='magic'?'Spell!':'Shot!',battle.e.x*unit,ground-220*unit);}for(const p of floating){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.font='bold 20px Nunito, sans-serif';ctx.textAlign='center';ctx.fillText(p.text,p.x*unit,ground-130*unit-(1-p.life)*50);}ctx.globalAlpha=1;}
 else if(view==='choose'){const keys=['dwarf','ranger','mage'];if(meta.thorn)keys.push('thorn');const scale=Math.min(.85,W/(keys.length*210),H/750);keys.forEach((k,i)=>hero(ctx,art,k,screen.querySelector(`[data-hero="${k}"]`).getBoundingClientRect().x+screen.querySelector(`[data-hero="${k}"]`).getBoundingClientRect().width/2,H*.55,emptyGear(),{time,scale:chosen===k?scale*1.12:scale}));}
 else if(view==='lobby'){const offers=run.wins===5?[master()]:run.offers;offers.forEach((o,i)=>hero(ctx,art,o.hero,W*(offers.length===1?.5:i===0?.27:.73),H*.48,o.gear,{time,face:i?-1:1,scale:Math.min(.85,W/480,H/720)}));}
 else if(view==='shop'){const box=$('.fitting-space').getBoundingClientRect();hero(ctx,art,run.hero,box.x+box.width/2,box.bottom-8,{...run.gear,[slot]:tier},{time,scale:Math.min(1.25,box.height/260)});}
}
function frame(now){const dt=Math.min(.05,(now-previous)/1000||0);previous=now;time+=dt;if(view==='fight'&&!paused()){acc+=dt;while(acc>=1/60&&view==='fight'){tick(battle,{...held,...taps},1/60);taps={};acc-=1/60;for(const e of battle.events)if(e.type==='hit'||e.type==='parry'||e.type==='evade')floating.push({x:e.x,text:e.type==='hit'?`−${e.damage}`:e.type==='parry'?'Parry!':'Nice dodge!',color:e.type==='hit'?'#fff0bd':'#a5f6e6',life:1});if(battle.outcome){settle(run,battle,meta);save();view='result';render();}}for(const p of floating)p.life-=dt;floating=floating.filter(p=>p.life>0);for(const [id,a]of [['p',battle.p],['e',battle.e]]){const m=$(`#${id}hp`);m.max=a.stats.hp;m.value=a.hp;$(`#${id}hptext`).textContent=`${a.hp} / ${a.stats.hp}`;}$('#countdown').textContent=battle.countdown>0?Math.ceil(battle.countdown):'';$('#energy').textContent=`Energy ${Math.floor(battle.p.energy)} / 100${battle.p.magicCD>0?` · Magic ${battle.p.magicCD.toFixed(1)}s`:''}`;$('#battle-note').textContent=battle.training?'Training · no rewards':battle.time<6?'Move close to strike. Jump over shots.':'';}else acc=0;draw();requestAnimationFrame(frame);}
try{art=await assets();$('#loading').hidden=true;render();requestAnimationFrame(frame);}catch(e){$('#loading').textContent='The arena could not load. Refresh to try again.';console.error(e);}
